import os, re, sys, json

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s05"
FREE_RE = re.compile(r'\b(kfree_skb|consume_skb|dev_kfree_skb_irq|dev_kfree_skb_any|dev_kfree_skb|napi_consume_skb|skb_unref|__kfree_skb)\s*\(')
HANDOFF_RE = re.compile(r'\b(skb_queue_tail|skb_queue_head|sock_queue_rcv_skb|sock_queue_err_skb|netif_rx|netif_rx_ni|netif_receive_skb|__netif_receive_skb|netif_rx_internal|enqueue_to_backlog|dev_queue_xmit|__dev_queue_xmit|nf_hook|ip_local_out|dst_output)\s*\(')
SAVE_RE = re.compile(r'^[^=]*?([A-Za-z_][\w]*)\s*=\s*[^;]*?\bskb->data\b[^;]*;')

results = []
for base in ("net", "drivers/net"):
    for dirpath, dirs, files in os.walk(os.path.join(ROOT, base)):
        for fn in files:
            if not fn.endswith(".c"): continue
            path = os.path.join(dirpath, fn)
            rel = os.path.relpath(path, ROOT)
            try:
                lines = open(path, errors="replace").read().splitlines()
            except Exception:
                continue
            for i, line in enumerate(lines):
                m = SAVE_RE.match(line.strip())
                if not m: continue
                var = m.group(1)
                # look ahead window for free or handoff of skb
                for j in range(i+1, min(i+31, len(lines))):
                    l2 = lines[j]
                    if FREE_RE.search(l2) and re.search(r'\b(skb|[^_]skbs?)\s*[,)]', l2.replace(' ','')):
                        # check var used after free within next 25 lines
                        for k in range(j+1, min(j+26, len(lines))):
                            l3 = lines[k]
                            if re.search(r'\b'+re.escape(var)+r'\b', l3):
                                results.append((rel, i+1, var, j+1, 'free', l2.strip(), k+1, l3.strip()))
                                break
                        break
                    if HANDOFF_RE.search(l2):
                        for k in range(j+1, min(j+26, len(lines))):
                            l3 = lines[k]
                            if re.search(r'\b'+re.escape(var)+r'\b', l3):
                                results.append((rel, i+1, var, j+1, 'handoff', l2.strip(), k+1, l3.strip()))
                                break
                        break

out = json.dumps(results, indent=1)
open(os.path.join(os.environ.get("TMPDIR","/tmp"), "scan_results.json"), "w").write(out)
print(len(results))
for r in results[:60]:
    print(f"{r[0]}:{r[1]} var={r[2]} {r[4]}@{r[3]}: {r[5]}  USE@{r[6]}: {r[7]}")
EOF
python3 $TMPDIR/scan.py

